public class LruAccessCacheTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            LruAccessCache cache = new LruAccessCache(3);
            cache.put("a", 1);
            cache.put("b", 2);
            cache.put("c", 3);
            check("insertion order before any read", "[a, b, c]", cache.keysOldestFirst().toString());
            check("a reads back", 1, cache.get("a"));
            check("reading a promotes it", "[b, c, a]", cache.keysOldestFirst().toString());
            cache.put("d", 4);
            check("least recently used was evicted", "[c, a, d]", cache.keysOldestFirst().toString());
            check("b is gone", null, cache.get("b"));
            check("a survived", 1, cache.get("a"));
            check("size never exceeds capacity", 3, cache.size());
            cache.put("c", 30);
            check("re-put updates the value", 30, cache.get("c"));
            check("re-put does not grow the cache", 3, cache.size());
            check("miss on an unknown key", null, cache.get("zzz"));
        } catch (Throwable t) {
            broke("LruAccessCache", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

